-- ARCHIVO GENERADO por scripts/generar-datos.mjs. Ejecútalo DESPUÉS de schema.sql y policies.sql.
on conflict (id) do update set
  level_id = excluded.level_id, position = excluded.position, question_text = excluded.question_text,
  options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation,
  time_limit = excluded.time_limit;
